import { FixedClock } from '@/shared-kernel';
import { Invoice, InvoiceSource } from '../domain/invoice';
import { SourceAlreadyInvoicedError } from '../domain/invoice.errors';
import { InvoiceRepository, ProcedureChargeQuery } from '../domain/invoice.repository';
import { PriceList } from '../domain/price-list';
import { InvoicingService } from './invoicing.service';

class InMemoryInvoiceRepository extends InvoiceRepository {
  readonly items: Invoice[] = [];

  async existsForSource(source: InvoiceSource) {
    return (await this.findBySource(source)) !== null;
  }

  async hasProcedureCharge(q: ProcedureChargeQuery) {
    return this.items.some((i) => {
      const s = i.toSnapshot();
      return (
        s.payerId === q.payerId &&
        s.practitionerId === q.practitionerId &&
        s.issuedAt >= q.from &&
        s.issuedAt <= q.to &&
        s.lines.some((l) => l.code === q.code)
      );
    });
  }

  async findByPayer(payerId: string) {
    return this.items.filter((i) => i.toSnapshot().payerId === payerId);
  }

  async findBySource(source: InvoiceSource) {
    return (
      this.items.find((i) => {
        const s = i.toSnapshot().source;
        return s.type === source.type && s.id === source.id;
      }) ?? null
    );
  }

  async save(invoice: Invoice) {
    this.items.push(invoice);
  }
}

describe('InvoicingService', () => {
  let repository: InMemoryInvoiceRepository;
  let service: InvoicingService;
  let clock: FixedClock;

  beforeEach(() => {
    repository = new InMemoryInvoiceRepository();
    clock = new FixedClock(new Date('2026-03-02T11:00:00Z'));
    service = new InvoicingService(repository, new PriceList(), clock);
  });

  it('prices the procedure codes of an encounter into a persisted invoice', async () => {
    await service.invoiceEncounter({ encounterId: 'e-1', payerId: 'person-1', practitionerId: 'dr-house', procedureCodes: ['10101012'] });

    expect(repository.items).toHaveLength(1);
    expect(repository.items[0].toSnapshot()).toMatchObject({
      payerId: 'person-1',
      source: { type: 'ENCOUNTER', id: 'e-1' },
      lines: [{ code: '10101012', amountCents: 25_000 }],
    });
  });

  it('never invoices the same encounter twice', async () => {
    const input = { encounterId: 'e-1', payerId: 'person-1', practitionerId: 'dr-house', procedureCodes: ['10101012'] };
    await service.invoiceEncounter(input);

    await expect(service.invoiceEncounter(input)).rejects.toThrow(SourceAlreadyInvoicedError);
    expect(repository.items).toHaveLength(1);
  });

  it('charges the no-show fee once per appointment', async () => {
    await service.chargeNoShow({ appointmentId: 'appt-1', payerId: 'person-1' });

    await expect(service.chargeNoShow({ appointmentId: 'appt-1', payerId: 'person-1' })).rejects.toThrow(
      SourceAlreadyInvoicedError,
    );
    expect(repository.items[0].totalCents).toBe(10_000);
  });

  describe('follow-up encounters', () => {
    const encounter = (id: string, procedureCodes: string[], practitionerId = 'dr-house', payerId = 'person-1') =>
      service.invoiceEncounter({ encounterId: id, payerId, practitionerId, procedureCodes });

    it('does not charge the consultation again within 30 days, but charges other procedures', async () => {
      await encounter('e-1', ['10101012']);
      clock.set(new Date('2026-03-20T11:00:00Z'));

      const invoice = await encounter('e-2', ['10101012', '40304361']);

      expect(invoice?.toSnapshot().lines).toEqual([expect.objectContaining({ code: '40304361', amountCents: 3_500 })]);
    });

    it('issues no invoice when a follow-up only had the consultation', async () => {
      await encounter('e-1', ['10101012']);
      clock.set(new Date('2026-03-20T11:00:00Z'));

      await expect(encounter('e-2', ['10101012'])).resolves.toBeNull();
      expect(repository.items).toHaveLength(1);
    });

    it('still protects against invoicing the same encounter twice when the follow-up was waived', async () => {
      await encounter('e-1', ['10101012']);
      clock.set(new Date('2026-03-20T11:00:00Z'));
      await encounter('e-2', ['40304361', '10101012']);

      await expect(encounter('e-2', ['40304361'])).rejects.toThrow(SourceAlreadyInvoicedError);
    });

    it('charges the consultation on the 30th day, but not after it', async () => {
      await encounter('e-1', ['10101012']);

      clock.set(new Date('2026-04-01T11:00:00Z'));
      expect(await encounter('e-2', ['10101012'])).toBeNull();

      clock.set(new Date('2026-04-01T11:00:01Z'));
      const late = await encounter('e-3', ['10101012']);
      expect(late?.totalCents).toBe(25_000);
    });

    it('charges the consultation again for another practitioner or another payer', async () => {
      await encounter('e-1', ['10101012']);
      clock.set(new Date('2026-03-10T11:00:00Z'));

      expect((await encounter('e-2', ['10101012'], 'dr-wilson'))?.totalCents).toBe(25_000);
      expect((await encounter('e-3', ['10101012'], 'dr-house', 'person-2'))?.totalCents).toBe(25_000);
    });

    it('does not count a no-show fee or an earlier waived follow-up as a consultation', async () => {
      await service.chargeNoShow({ appointmentId: 'appt-1', payerId: 'person-1' });

      expect((await encounter('e-1', ['10101012']))?.totalCents).toBe(25_000);
    });
  });
});
